package com.bingoluck;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Keeps the player's own kill/completion counters current without needing the collection log
 * to be reopened. A counter starts from an exact value (a collection log page, or a kill count
 * chat message) and is then advanced by NPC loot events, the same approach Dink uses. Opening
 * the collection log page again re-syncs any drift.
 *
 * Only counters that have been seeded are ever advanced, and only the player's own counters are
 * kept. State is saved per RuneLite profile so it survives restarts.
 */
@Slf4j
@Singleton
class KillCountTracker
{
	private static final String CONFIG_KEY = "killCounts";
	/** Collection log lines look like "Tormented Demon kills: 1,124" or "Tombs of Amascut (Expert) completions: 48". */
	private static final Pattern PAGE_LINE = Pattern.compile("^(.+?): ?([0-9][0-9,]*)$");
	private static final Pattern SUFFIX = Pattern.compile("\\s+(kills|completions|kill count|harvests|opened)$", Pattern.CASE_INSENSITIVE);

	private final ConfigManager configManager;

	/** display name -> kc, in insertion order. */
	private final Map<String, Integer> counts = new LinkedHashMap<>();
	/** lower-case name -> display name, for matching NPC and chat names to a counter. */
	private final Map<String, String> byLowerName = new LinkedHashMap<>();
	private boolean loaded;
	private boolean dirty;
	private boolean unsaved;                           // changed since the last write to the profile

	@Inject
	KillCountTracker(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/** Loads saved counters for the current profile; call once logged in. */
	synchronized void loadIfNeeded()
	{
		if (loaded)
		{
			return;
		}
		String saved = configManager.getRSProfileConfiguration(BingoLuckSyncConfig.GROUP, CONFIG_KEY);
		if (saved != null)
		{
			for (String line : saved.split("\n"))
			{
				int tab = line.lastIndexOf('\t');
				if (tab > 0)
				{
					try
					{
						put(line.substring(0, tab), Integer.parseInt(line.substring(tab + 1).trim()), false);
					}
					catch (NumberFormatException ignored)
					{
						// skip a corrupt line
					}
				}
			}
		}
		loaded = true;
		dirty = !counts.isEmpty();                     // saved but possibly never sent: send them again on this login
	}

	synchronized void reset()
	{
		counts.clear();
		byLowerName.clear();
		loaded = false;
		dirty = false;
	}

	/** Seeds/overwrites counters from a collection log page's kill count lines. */
	synchronized void onPageLines(List<String> lines)
	{
		for (String line : lines)
		{
			Matcher m = PAGE_LINE.matcher(line.trim());
			if (!m.matches() || line.startsWith("Personal Best"))
			{
				continue;
			}
			try
			{
				put(stripSuffix(m.group(1)), Integer.parseInt(m.group(2).replace(",", "")), true);
			}
			catch (NumberFormatException ignored)
			{
				// not a number we can use
			}
		}
	}

	/** Adds a kill when a tracked NPC dies and drops loot. Ignored unless that counter was seeded. */
	synchronized void onNpcLoot(String npcName)
	{
		String display = npcName == null ? null : byLowerName.get(npcName.toLowerCase(Locale.ROOT));
		if (display != null)
		{
			put(display, counts.get(display) + 1, true);
		}
	}

	/**
	 * A "Your X kill count is: N" chat message is exact, so it corrects a counter. It only
	 * touches counters a collection log page has already seeded, so a chat name that differs
	 * from the page's own label can't create a duplicate.
	 */
	synchronized void onChatKillCount(String boss, int kc)
	{
		String display = byLowerName.get(boss.toLowerCase(Locale.ROOT));
		if (display != null)
		{
			put(display, kc, true);
		}
	}

	/** A raid completion message is exact too. Names match the collection log's own labels. */
	synchronized void onRaidKillCount(String raid, String mode, int kc)
	{
		put(raidCounterName(raid, mode), kc, true);
	}

	static String raidCounterName(String raid, String mode)
	{
		switch (mode)
		{
			case "CHALLENGE":
				return raid + " (CM)";
			case "HARD":
				return raid + " (Hard)";
			case "ENTRY":
				return raid + " (Entry)";
			case "EXPERT":
				return raid + " (Expert)";
			case "STORY":
				return raid + " (Story)";
			default:
				return raid;
		}
	}

	/** Snapshot to send, or null if nothing changed since the last one. */
	synchronized List<KillCountData.Count> takeDirtySnapshot()
	{
		if (!dirty || counts.isEmpty())
		{
			return null;
		}
		dirty = false;
		List<KillCountData.Count> out = new ArrayList<>(counts.size());
		for (Map.Entry<String, Integer> e : counts.entrySet())
		{
			out.add(new KillCountData.Count(e.getKey(), e.getValue()));
		}
		return out;
	}

	/** Saves counters to the RuneLite profile. Call off the hot path (it is a config write). */
	/** Writes the counters to the profile only if something changed since the last write. */
	synchronized void saveIfChanged()
	{
		if (unsaved)
		{
			save();
		}
	}

	synchronized void save()
	{
		if (!loaded)
		{
			return;
		}
		unsaved = false;
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, Integer> e : counts.entrySet())
		{
			sb.append(e.getKey()).append('\t').append(e.getValue()).append('\n');
		}
		configManager.setRSProfileConfiguration(BingoLuckSyncConfig.GROUP, CONFIG_KEY, sb.toString());
	}

	private void put(String name, int kc, boolean markDirty)
	{
		if (name.isEmpty() || kc < 0)
		{
			return;
		}
		Integer old = counts.put(name, kc);
		byLowerName.put(name.toLowerCase(Locale.ROOT), name);
		if (old == null || old != kc)
		{
			unsaved = true;
			if (markDirty)
			{
				dirty = true;
			}
		}
	}

	private static String stripSuffix(String label)
	{
		return SUFFIX.matcher(label.trim()).replaceFirst("").trim();
	}
}

package com.bingoluck;

import lombok.Builder;
import lombok.Value;

/**
 * A finished raid as seen by the local player. Fields that the game does not expose
 * for a given raid are left null/-1 and the server decides how to handle them.
 */
@Value
@Builder(toBuilder = true)
class RaidCompletion
{
	/** COX, TOB or TOA. */
	String raid;
	/** NORMAL, CHALLENGE, STORY, HARD, ENTRY or EXPERT. */
	String mode;
	String player;
	/** Completion count for this raid and mode, or -1 if it could not be read. */
	int killCount;
	/** Epoch seconds when the completion was recorded locally. */
	long completedAt;
	/** Team total points (CoX only; the game exposes it), otherwise -1. */
	int totalPoints;
	/** Personal points. For ToA this excludes the 5,000 starting points; -1 if unknown. */
	int personalPoints;
	/** ToA raid level, otherwise -1. */
	int raidLevel;
	/** Number of players, or -1 if unknown. CoX is sent as the game displays it (e.g. "24+"). */
	int teamSize;
	String teamSizeLabel;
	/** ToB only: your own death count from the end-of-raid performance board, otherwise -1. */
	int deaths;
	/** ToB only: total deaths across the whole team (a number, no names), otherwise -1. */
	int teamDeaths;
	/** ToB only: 1 if you were the raid MVP, 0 if not, -1 if unknown. */
	int mvp;
}

package com.bingoluck;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Sends the player's own data to the configured server. All calls are asynchronous
 * (OkHttp thread pool) and never run on the client thread.
 *
 * A request that fails because the server is busy, asleep or unreachable (429, 5xx or a network
 * error) is retried a few times with a growing delay, so a page opened in the collection log or a
 * raid that just finished isn't silently lost. The server treats every upload as an upsert, so a
 * retry can never double count. Requests the server refuses outright (a bad token, a bad payload)
 * are not retried.
 */
@Slf4j
@Singleton
class SyncClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	// Not final so tests can point the client at a local server and shorten the waits.
	String baseUrl = "https://osrsbingobot.onrender.com";
	long[] retryDelaysSeconds = {5, 30, 120};

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final Set<ScheduledFuture<?>> pendingRetries = ConcurrentHashMap.newKeySet();
	private volatile boolean stopped;
	private volatile Listener listener;

	/** Told about the two outcomes a player can act on. Called on a background thread. */
	interface Listener
	{
		/** The server refused the plugin token (HTTP 401). Retrying can't fix that. */
		void onTokenRejected();

		/** An upload failed on every retry (server busy, down, or unreachable). */
		void onGaveUp(String path);
	}

	@Inject
	SyncClient(OkHttpClient okHttpClient, Gson gson, ScheduledExecutorService executor)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.executor = executor;
	}

	void start()
	{
		stopped = false;
	}

	void setListener(Listener listener)
	{
		this.listener = listener;
	}

	/** Cancels retries that are still waiting. Called when the plugin shuts down. */
	void stop()
	{
		stopped = true;
		for (ScheduledFuture<?> future : pendingRetries)
		{
			future.cancel(false);
		}
		pendingRetries.clear();
	}

	void postCollectionLogPage(String token, CollectionLogPageData page)
	{
		post("/plugin/collection-log", token, page);
	}

	void postRaid(String token, RaidCompletion raid)
	{
		post("/plugin/raid", token, raid);
	}

	void postKillCounts(String token, KillCountData data)
	{
		post("/plugin/kc", token, data);
	}

	void postDoomDelves(String token, DoomDelveData data)
	{
		post("/plugin/doom", token, data);
	}

	private void post(String path, String token, Object body)
	{
		HttpUrl url = HttpUrl.parse(baseUrl + path);
		if (url == null || token == null || token.isEmpty())
		{
			return;
		}

		String json = gson.toJson(body);
		log.debug("Sending to {}: {}", path, json);
		send(url, path, token, json, 0);
	}

	private void send(HttpUrl url, String path, String token, String json, int attempt)
	{
		Request request = new Request.Builder()
			.url(url)
			.header("X-Plugin-Token", token)
			.post(RequestBody.create(JSON, json))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Sync to {} failed", path, e);
				retry(url, path, token, json, attempt);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.isSuccessful())
					{
						return;
					}
					log.debug("Sync to {} returned HTTP {}", path, r.code());
					if (r.code() == 401)
					{
						Listener l = listener;
						if (l != null && !stopped)
						{
							l.onTokenRejected();
						}
					}
					else if (r.code() == 429 || r.code() >= 500)
					{
						retry(url, path, token, json, attempt);
					}
				}
			}
		});
	}

	private void retry(HttpUrl url, String path, String token, String json, int attempt)
	{
		if (stopped)
		{
			return;
		}
		if (attempt >= retryDelaysSeconds.length)
		{
			Listener l = listener;
			if (l != null)
			{
				l.onGaveUp(path);
			}
			return;
		}

		long delay = retryDelaysSeconds[attempt];
		log.debug("Will retry {} in {}s (attempt {} of {})", path, delay, attempt + 2, retryDelaysSeconds.length + 1);
		pendingRetries.removeIf(ScheduledFuture::isDone);
		pendingRetries.add(executor.schedule(() ->
		{
			if (!stopped)
			{
				send(url, path, token, json, attempt + 1);
			}
		}, delay, TimeUnit.SECONDS));
	}
}

package com.bingoluck;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Counts Theatre of Blood deaths from the game's own chat lines, so a raid can be reported even when
 * the score board was never opened. Only a count for you and a count for the team are kept - other
 * players' names are compared against yours and then forgotten.
 */
class TobDeathTracker
{
	static final String ENTRY_MESSAGE = "You enter the Theatre of Blood";
	private static final Pattern DEATH = Pattern.compile("^(.+?) has died\\. Death count: ?([0-9,]+)");

	private boolean inRaid;
	private int myDeaths;
	private int teamDeaths;

	/** True once a raid has been entered, so there are live numbers to fall back on. */
	boolean isActive()
	{
		return inRaid;
	}

	int getMyDeaths()
	{
		return myDeaths;
	}

	int getTeamDeaths()
	{
		return teamDeaths;
	}

	void reset()
	{
		inRaid = false;
		myDeaths = 0;
		teamDeaths = 0;
	}

	/** Feed every game message (colour tags already removed). {@code me} is your sanitized name. */
	void onGameMessage(String message, String me)
	{
		if (message.contains(ENTRY_MESSAGE))
		{
			reset();
			inRaid = true;
			return;
		}
		if (!inRaid)
		{
			return;
		}
		Matcher m = DEATH.matcher(message);
		if (!m.find())
		{
			return;
		}
		int reported;
		try
		{
			reported = Integer.parseInt(m.group(2).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return;
		}
		// The line carries the running team total; counting lines too covers a total that is missing or lags.
		teamDeaths = Math.max(teamDeaths + 1, reported);
		if (me != null && me.equals(m.group(1).replace('\u00A0', ' ').trim()))
		{
			myDeaths++;
		}
	}
}

package com.bingoluck;

/**
 * Decides whether to tell the player, once, that the plugin has been updated. Works only from the
 * version stored in the player's own settings, so it needs no network call.
 */
final class UpdateNotice
{
	/** Bump this and {@link #SUMMARY} with each release, and add the matching entry to CHANGELOG.md. */
	static final String VERSION = "1.1";
	static final String SUMMARY = "Theatre of Blood deaths are now counted during the raid, and you'll be told in chat if syncing stops working.";
	static final String CHANGELOG_HINT = "Full list: github.com/Liam-Nagle/bingo-luck-sync (CHANGELOG.md)";

	private UpdateNotice()
	{
	}

	/**
	 * @param lastSeen     the version stored the last time this was checked, empty if never
	 * @param setUpAlready whether sync was already switched on or a token entered before this check -
	 *                     what tells someone updating from the first release from a brand-new install
	 */
	static boolean shouldAnnounce(String lastSeen, String current, boolean setUpAlready)
	{
		if (current.equals(lastSeen))
		{
			return false;
		}
		// Nothing stored: either a new install (say nothing) or an update from the first release (say so).
		return lastSeen != null && !lastSeen.isEmpty() || setUpAlready;
	}

	static String message()
	{
		return "updated to v" + VERSION + ". " + SUMMARY + " " + CHANGELOG_HINT;
	}
}

