package com.bingoluck;

import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DoomDelveTrackerTest
{
	// The tracker only touches the RuneLite config when loading/saving, which these tests don't do.
	private final DoomDelveTracker tracker = new DoomDelveTracker(null);

	@Test
	public void countsNothingUntilTheScoreboardHasBeenRead()
	{
		assertTrue(tracker.onGameMessage("Delve level: 5 duration: 1:23"));      // recognised, but no starting point
		assertNull(tracker.takeDirtySnapshot("Tester"));
	}

	@Test
	public void seedsFromTheScoreboardThenCountsEachCompletionByLevel()
	{
		tracker.seed(new int[]{10, 9, 8, 7, 6, 5, 4, 3}, 2);
		tracker.takeDirtySnapshot("Tester");                                     // clear the seed's change
		tracker.onGameMessage("Delve level: 5 duration: 1:23");
		tracker.onGameMessage("Delve level: 5 duration: 1:30");
		tracker.onGameMessage("Delve level: 8 duration: 2:00");
		tracker.onGameMessage("Delve level: 8+ duration: 2:10");
		tracker.onGameMessage("Delve level: 11 duration: 3:00");                 // deeper than 8 counts as 8+

		DoomDelveData data = tracker.takeDirtySnapshot("Tester");
		assertNotNull(data);
		assertEquals(Arrays.asList(10, 9, 8, 7, 8, 5, 4, 4), data.getLevels());
		assertEquals(4, data.getPast8());
		assertNull("nothing new since the last snapshot", tracker.takeDirtySnapshot("Tester"));
	}

	@Test
	public void countsDeepDelvesThatShowTheirDepthInBrackets()
	{
		tracker.seed(new int[]{10, 9, 8, 7, 6, 5, 4, 3}, 2);
		tracker.takeDirtySnapshot("Tester");
		// The game's own wording for a delve past level 8 puts the depth in brackets.
		assertTrue(tracker.onGameMessage("Delve level: 8+ (16) duration: 1:48.6. Personal best: 0:52.6"));
		assertTrue(tracker.onGameMessage("Delve level: 8+ (9) duration: 2:40.80 (new personal best)"));

		DoomDelveData data = tracker.takeDirtySnapshot("Tester");
		assertEquals(4, data.getPast8());
		assertEquals(3, data.getLevels().get(7).intValue());                     // level 8 itself is untouched
	}

	@Test
	public void ignoresUnrelatedMessages()
	{
		tracker.seed(new int[]{1, 1, 1, 1, 1, 1, 1, 1}, 0);
		tracker.takeDirtySnapshot("Tester");
		assertFalse(tracker.onGameMessage("Your completed Tombs of Amascut count is: 60."));
		assertFalse(tracker.onGameMessage("Delve level reached"));
		assertNull(tracker.takeDirtySnapshot("Tester"));
	}

	@Test
	public void theScoreboardCorrectsAnyDrift()
	{
		tracker.seed(new int[]{5, 5, 5, 5, 5, 5, 5, 5}, 0);
		tracker.onGameMessage("Delve level: 3 duration: 1:00");
		tracker.seed(new int[]{5, 5, 5, 5, 5, 5, 5, 5}, 0);                      // the game's record says level 3 is still 5
		assertEquals(5, tracker.takeDirtySnapshot("Tester").getLevels().get(2).intValue());
	}
}

package com.bingoluck;

import com.google.gson.Gson;
import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.util.Collections;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.OkHttpClient;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Checks the retry behaviour against a throwaway local server (no network, no real data). */
public class SyncClientTest
{
	private HttpServer server;
	private ScheduledExecutorService executor;
	private SyncClient client;
	private final AtomicInteger requests = new AtomicInteger();
	private volatile int[] script = {200};
	private CountDownLatch done;

	@Before
	public void setUp() throws Exception
	{
		server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/plugin/kc", exchange ->
		{
			int n = requests.getAndIncrement();
			int code = script[Math.min(n, script.length - 1)];
			exchange.getRequestBody().readAllBytes();
			exchange.sendResponseHeaders(code, -1);
			exchange.close();
			if (code == 200 || code == 401)
			{
				done.countDown();
			}
		});
		server.start();

		executor = Executors.newSingleThreadScheduledExecutor();
		client = new SyncClient(new OkHttpClient(), new Gson(), executor);
		client.baseUrl = "http://127.0.0.1:" + server.getAddress().getPort();
		client.retryDelaysSeconds = new long[]{0, 0, 0};
		client.start();
	}

	@After
	public void tearDown()
	{
		client.stop();
		executor.shutdownNow();
		server.stop(0);
	}

	private void send()
	{
		client.postKillCounts("token", new KillCountData("Tester", Collections.singletonList(new KillCountData.Count("Tormented Demon", 5))));
	}

	@Test
	public void retriesWhenTheServerIsBusyThenSucceeds() throws Exception
	{
		script = new int[]{503, 429, 200};
		done = new CountDownLatch(1);
		send();
		assertTrue("never succeeded", done.await(10, TimeUnit.SECONDS));
		assertEquals(3, requests.get());
	}

	@Test
	public void doesNotRetryARefusedToken() throws Exception
	{
		script = new int[]{401};
		done = new CountDownLatch(1);
		send();
		assertTrue(done.await(10, TimeUnit.SECONDS));
		Thread.sleep(500);
		assertEquals(1, requests.get());
	}

	@Test
	public void givesUpAfterTheLastRetry() throws Exception
	{
		script = new int[]{503};
		done = new CountDownLatch(1);
		send();
		Thread.sleep(1500);
		assertEquals(4, requests.get());          // the first attempt plus three retries
	}

	@Test
	public void stopCancelsPendingRetries() throws Exception
	{
		client.retryDelaysSeconds = new long[]{2, 2, 2};
		script = new int[]{503};
		done = new CountDownLatch(1);
		send();
		Thread.sleep(300);
		client.stop();
		Thread.sleep(2500);
		assertEquals(1, requests.get());
	}

	/** Counts what the client reports to its listener. */
	private static final class CountingListener implements SyncClient.Listener
	{
		final AtomicInteger rejected = new AtomicInteger();
		final AtomicInteger gaveUp = new AtomicInteger();

		@Override
		public void onTokenRejected()
		{
			rejected.incrementAndGet();
		}

		@Override
		public void onGaveUp(String path)
		{
			gaveUp.incrementAndGet();
		}
	}

	@Test
	public void reportsARefusedTokenButIsNotTreatedAsAFailure() throws Exception
	{
		CountingListener listener = new CountingListener();
		client.setListener(listener);
		script = new int[]{401};
		done = new CountDownLatch(1);
		send();
		assertTrue(done.await(10, TimeUnit.SECONDS));
		Thread.sleep(500);
		assertEquals(1, listener.rejected.get());
		assertEquals("a refused token is not 'couldn't reach the server'", 0, listener.gaveUp.get());
	}

	@Test
	public void reportsGivingUpOnlyAfterEveryRetryFailed() throws Exception
	{
		CountingListener listener = new CountingListener();
		client.setListener(listener);
		script = new int[]{503};
		done = new CountDownLatch(1);
		send();
		Thread.sleep(1500);
		assertEquals(4, requests.get());
		assertEquals(1, listener.gaveUp.get());
		assertEquals(0, listener.rejected.get());
	}

	@Test
	public void staysQuietWhenARetrySucceeds() throws Exception
	{
		CountingListener listener = new CountingListener();
		client.setListener(listener);
		script = new int[]{503, 429, 200};
		done = new CountDownLatch(1);
		send();
		assertTrue(done.await(10, TimeUnit.SECONDS));
		Thread.sleep(300);
		assertEquals(0, listener.gaveUp.get());
		assertEquals(0, listener.rejected.get());
	}

	@Test
	public void staysQuietAfterStop() throws Exception
	{
		CountingListener listener = new CountingListener();
		client.setListener(listener);
		client.retryDelaysSeconds = new long[]{1, 1, 1};
		script = new int[]{503};
		done = new CountDownLatch(1);
		send();
		Thread.sleep(200);
		client.stop();
		Thread.sleep(1500);
		assertEquals("a plugin that has shut down must not talk", 0, listener.gaveUp.get());
	}
}

package com.bingoluck;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TobDeathTrackerTest
{
	@Test
	public void ignoresDeathsOutsideARaid()
	{
		TobDeathTracker t = new TobDeathTracker();
		t.onGameMessage("Bob has died. Death count: 1", "Me");
		assertFalse(t.isActive());
		assertEquals(0, t.getTeamDeaths());
	}

	@Test
	public void countsYourDeathsAndTheTeams()
	{
		TobDeathTracker t = new TobDeathTracker();
		t.onGameMessage("You enter the Theatre of Blood (Normal Mode).", "Me");
		t.onGameMessage("Bob has died. Death count: 1", "Me");
		t.onGameMessage("Me has died. Death count: 2", "Me");
		t.onGameMessage("Me has died. Death count: 3", "Me");
		assertTrue(t.isActive());
		assertEquals(2, t.getMyDeaths());
		assertEquals(3, t.getTeamDeaths());
	}

	@Test
	public void entryResetsThePreviousRaid()
	{
		TobDeathTracker t = new TobDeathTracker();
		t.onGameMessage("You enter the Theatre of Blood", "Me");
		t.onGameMessage("Me has died. Death count: 1", "Me");
		t.onGameMessage("You enter the Theatre of Blood", "Me");
		assertEquals(0, t.getMyDeaths());
		assertEquals(0, t.getTeamDeaths());
	}

	@Test
	public void namesWithNonBreakingSpacesStillMatch()
	{
		TobDeathTracker t = new TobDeathTracker();
		t.onGameMessage("You enter the Theatre of Blood", "IM Thorgrim");
		t.onGameMessage("IM\u00A0Thorgrim has died. Death count: 1", "IM Thorgrim");
		assertEquals(1, t.getMyDeaths());
	}

	@Test
	public void unrelatedMessagesAreIgnored()
	{
		TobDeathTracker t = new TobDeathTracker();
		t.onGameMessage("You enter the Theatre of Blood", "Me");
		t.onGameMessage("Oh dear, you are dead!", "Me");
		t.onGameMessage("Bob has died. Death count: lots", "Me");
		assertEquals(0, t.getTeamDeaths());
	}
}

package com.bingoluck;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class UpdateNoticeTest
{
	@Test
	public void brandNewInstallIsLeftAlone()
	{
		assertFalse(UpdateNotice.shouldAnnounce("", "1.1", false));
		assertFalse(UpdateNotice.shouldAnnounce(null, "1.1", false));
	}

	@Test
	public void updatingFromTheFirstReleaseIsAnnounced()
	{
		assertTrue(UpdateNotice.shouldAnnounce("", "1.1", true));
	}

	@Test
	public void anOlderStoredVersionIsAnnounced()
	{
		assertTrue(UpdateNotice.shouldAnnounce("1.0", "1.1", false));
	}

	@Test
	public void theSameVersionIsNotAnnouncedAgain()
	{
		assertFalse(UpdateNotice.shouldAnnounce("1.1", "1.1", true));
	}
}
